package com.codeguardian.service; import com.codeguardian.dto.*; import com.codeguardian.entity.*; import com.codeguardian.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.scheduling.annotation.Async; import org.springframework.stereotype.Service; import java.util.*; @Service @RequiredArgsConstructor public class CicdService{private final ReviewService reviews;private final ReviewTaskRepository tasks;private final FindingRepository findings;public ReviewResponseDTO trigger(ReviewRequestDTO r){r.setReviewType("GIT");return reviews.createReviewTask(r);}@Async public void handleWebhook(Map<String,Object> payload){Object url=payload.get("repositoryUrl");if(url!=null)trigger(ReviewRequestDTO.builder().taskName("Webhook review").gitUrl(String.valueOf(url)).build());}public Map<String,Object> qualityGate(Long taskId){ReviewTask t=tasks.findById(taskId).orElseThrow();List<Finding> fs=findings.findByTaskId(taskId);boolean passed=fs.stream().noneMatch(f->"CRITICAL".equalsIgnoreCase(f.getSeverity())||"HIGH".equalsIgnoreCase(f.getSeverity()));return Map.of("taskId",taskId,"status",t.getStatus(),"passed",passed,"findingCount",fs.size());}}
